import { realpathSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { parseArgs } from 'node:util';
import { BacklogError } from '../engine/backlog.js';
import { ConfigError } from '../engine/config.js';
import { RunError, runDemo, runTally } from '../engine/run.js';

export const COMMANDS = ['run', 'demo', 'init', 'doctor'] as const;
export type Command = (typeof COMMANDS)[number];

export const VERSION = '0.1.0';

export interface CliOptions {
  /** Path to tally.yaml. */
  config: string;
  /** Simulated workers with scripted outcomes; spends nothing. */
  dryRun: boolean;
  /** Send every task to the strongest tier, for the before/after comparison. */
  baseline: boolean;
  /** Overrides the budget in tally.yaml. */
  budgetUsd: number | undefined;
  /** Run a single task by id or issue number. */
  only: string | undefined;
}

export type ParsedCli =
  | { kind: 'command'; command: Command; options: CliOptions }
  | { kind: 'help' }
  | { kind: 'version' }
  | { kind: 'error'; message: string };

export interface CliIO {
  stdout: (line: string) => void;
  stderr: (line: string) => void;
}

const USAGE = `tally: a CFO for a fleet of coding agents

Usage: tally <command> [options]

Commands:
  run      Run the backlog against the budget in tally.yaml
  demo     Run the full loop with simulated workers on a sample backlog
  init     Set up tally.yaml for the current repository
  doctor   Check that each integration is connected

Options:
  --config <path>   Path to tally.yaml (default: tally.yaml)
  --dry-run         Simulate workers; spends nothing
  --budget <usd>    Override the budget for this run
  --only <task>     Run a single task
  --baseline        Send every task to the strongest tier
  -h, --help        Show this help
  -v, --version     Show the version`;

export function parseCli(argv: string[]): ParsedCli {
  let parsed;
  try {
    parsed = parseArgs({
      args: argv,
      allowPositionals: true,
      options: {
        config: { type: 'string', default: 'tally.yaml' },
        'dry-run': { type: 'boolean', default: false },
        baseline: { type: 'boolean', default: false },
        budget: { type: 'string' },
        only: { type: 'string' },
        help: { type: 'boolean', short: 'h', default: false },
        version: { type: 'boolean', short: 'v', default: false },
      },
    });
  } catch (e) {
    return { kind: 'error', message: (e as Error).message };
  }
  const { values, positionals } = parsed;
  if (values.help) return { kind: 'help' };
  if (values.version) return { kind: 'version' };
  const [name, ...extra] = positionals;
  if (name === undefined) return { kind: 'help' };
  if (!(COMMANDS as readonly string[]).includes(name)) {
    return { kind: 'error', message: `unknown command "${name}"; expected one of ${COMMANDS.join(', ')}` };
  }
  if (extra.length > 0) return { kind: 'error', message: `unexpected argument "${extra[0]}"` };

  let budgetUsd: number | undefined;
  if (values.budget !== undefined) {
    budgetUsd = Number(values.budget);
    if (!Number.isFinite(budgetUsd) || budgetUsd <= 0) {
      return { kind: 'error', message: `--budget must be a positive number of USD, got "${values.budget}"` };
    }
  }
  return {
    kind: 'command',
    command: name as Command,
    options: {
      config: values.config,
      dryRun: values['dry-run'],
      baseline: values.baseline,
      budgetUsd,
      only: values.only,
    },
  };
}

type Handler = (options: CliOptions, io: CliIO) => Promise<number>;

const stub =
  (command: Command): Handler =>
  async (_options, io) => {
    io.stdout(`tally ${command}: not implemented yet`);
    return 0;
  };

async function runCommand(options: CliOptions, io: CliIO): Promise<number> {
  try {
    const result = await runTally({
      configPath: options.config,
      dryRun: options.dryRun,
      baseline: options.baseline,
      budgetUsd: options.budgetUsd,
      only: options.only,
    });
    io.stdout(`wrote ${result.runStatePath}`);
    io.stdout(`wrote ${result.ledgerPath}`);
    io.stdout(`finished ${result.runState.runId}: ${result.runState.tasks.length} tasks, ${result.ledger.length} attempts`);
    return 0;
  } catch (e) {
    return reportError('tally run', e, io);
  }
}

async function demoCommand(_options: CliOptions, io: CliIO): Promise<number> {
  try {
    const result = await runDemo();
    io.stdout(`wrote ${result.runStatePath}`);
    io.stdout(`wrote ${result.ledgerPath}`);
    io.stdout(`finished ${result.runState.runId}: ${result.runState.tasks.length} tasks, ${result.ledger.length} attempts`);
    return 0;
  } catch (e) {
    return reportError('tally demo', e, io);
  }
}

function reportError(prefix: string, error: unknown, io: CliIO): number {
  if (error instanceof ConfigError || error instanceof BacklogError || error instanceof RunError) {
    io.stderr(`${prefix}: ${error.message}`);
    return 2;
  }
  throw error;
}

const handlers: Record<Command, Handler> = {
  run: runCommand,
  demo: demoCommand,
  init: stub('init'),
  doctor: stub('doctor'),
};

const consoleIO: CliIO = {
  stdout: (line) => console.log(line),
  stderr: (line) => console.error(line),
};

/** Returns the process exit code. */
export async function main(argv: string[], io: CliIO = consoleIO): Promise<number> {
  const parsed = parseCli(argv);
  switch (parsed.kind) {
    case 'help':
      io.stdout(USAGE);
      return 0;
    case 'version':
      io.stdout(VERSION);
      return 0;
    case 'error':
      io.stderr(`tally: ${parsed.message}`);
      io.stderr('Run `tally --help` for usage.');
      return 2;
    case 'command':
      return handlers[parsed.command](parsed.options, io);
  }
}

const invokedDirectly = process.argv[1] !== undefined && realpathSync(process.argv[1]) === fileURLToPath(import.meta.url);
if (invokedDirectly) {
  process.exitCode = await main(process.argv.slice(2));
}
import { mkdtempSync, readFileSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { describe, expect, it } from 'vitest';
import { validateLedger, validateRunState } from '../schema/index.js';
import { runDemo, runTally } from './run.js';

const fixedNow = () => new Date('2026-10-11T03:00:00.000Z');

function writeFixture() {
  const dir = mkdtempSync(join(tmpdir(), 'tally-run-'));
  const configPath = join(dir, 'tally.yaml');
  const backlogPath = join(dir, 'backlog.yaml');
  writeFileSync(
    configPath,
    `version: 1
repo: { path: ".", slug: "acme/payments-service", baseBranch: "main" }
test: { command: "npm test" }
backlog: { source: "file", file: "backlog.yaml" }
tiers:
  - name: cheap
    harness: claude-code
    provider: litellm
    model: nova-micro
    price: { inputUsdPerMTok: 0.035, cachedInputUsdPerMTok: 0.00875, outputUsdPerMTok: 0.14 }
    ceilingFraction: 0.2
  - name: middle
    harness: claude-code
    provider: litellm
    model: claude-sonnet-4.6
    price: { inputUsdPerMTok: 3.3, cachedInputUsdPerMTok: 0.33, outputUsdPerMTok: 16.5 }
    ceilingFraction: 0.5
  - name: top
    harness: claude-code
    provider: litellm
    model: claude-opus-4.6
    price: { inputUsdPerMTok: 5.5, cachedInputUsdPerMTok: 0.55, outputUsdPerMTok: 27.5 }
    ceilingFraction: 1
ceilings:
  bySizeUsd: { small: 1, medium: 4, large: 10 }
budget: { source: config, usd: 40 }
concurrency: 3
integrations: { neatlogs: false, entire: true, cfoai: false, slack: false }
`,
  );
  writeFileSync(
    backlogPath,
    `tasks:
  - id: T1
    title: Reject negative amounts
    size: small
    outcomes: [passed]
  - id: T2
    title: Add idempotency keys
    size: medium
    outcomes: [stopped, passed]
  - id: T3
    title: Move ledger writes into a transaction
    size: large
    outcomes: [passed]
`,
  );
  return { dir, configPath };
}

describe('runTally dry-run', () => {
  it('writes valid run state and ledger files with an escalated attempt', async () => {
    const { dir, configPath } = writeFixture();
    const outputDir = join(dir, 'out');
    const result = await runTally({ configPath, dryRun: true, baseline: false, outputDir, now: fixedNow });

    expect(result.runState.runId).toBe('run-20261011-030000Z');
    expect(result.runState.tasks).toHaveLength(3);
    expect(result.ledger.map((row) => `${row.taskId}:${row.attempt}:${row.result}:${row.tier}`)).toEqual([
      'T1:1:passed:cheap',
      'T2:1:stopped:middle',
      'T2:2:passed:top',
      'T3:1:passed:top',
    ]);
    expect(result.runState.tasks[1]).toMatchObject({ status: 'passed', attempts: 2, escalated: true, tier: 'top' });
    expect(result.runState.budget.spentNanos).toBe(result.ledger.reduce((sum, row) => sum + row.estimatedCostNanos, 0));
    expect(validateRunState(JSON.parse(readFileSync(result.runStatePath, 'utf8'))).ok).toBe(true);
    expect(validateLedger(JSON.parse(readFileSync(result.ledgerPath, 'utf8'))).ok).toBe(true);
  });

  it('runs a single task by id and can force baseline routing', async () => {
    const { dir, configPath } = writeFixture();
    const result = await runTally({
      configPath,
      dryRun: true,
      baseline: true,
      only: 'T1',
      outputDir: join(dir, 'baseline'),
      now: fixedNow,
    });

    expect(result.runState.mode).toBe('baseline');
    expect(result.runState.tasks).toHaveLength(1);
    expect(result.ledger).toHaveLength(1);
    expect(result.ledger[0]).toMatchObject({ taskId: 'T1', tier: 'top', model: 'claude-opus-4.6' });
  });

  it('marks tasks skipped when the configured budget cannot reserve their ceiling', async () => {
    const { dir, configPath } = writeFixture();
    const result = await runTally({ configPath, dryRun: true, baseline: false, budgetUsd: 0.01, outputDir: join(dir, 'tiny'), now: fixedNow });

    expect(result.ledger).toHaveLength(0);
    expect(result.runState.tasks.every((task) => task.status === 'skipped')).toBe(true);
    expect(result.runState.tasks.every((task) => task.statusReason === 'not started: no budget')).toBe(true);
  });
});

describe('runDemo', () => {
  it('produces a dry-run ledger without a user config file', async () => {
    const dir = mkdtempSync(join(tmpdir(), 'tally-demo-out-'));
    const result = await runDemo({ outputDir: dir, now: fixedNow });

    expect(result.runState.dryRun).toBe(true);
    expect(result.ledger.some((row) => row.escalatedFrom !== null)).toBe(true);
    expect(validateRunState(result.runState).ok).toBe(true);
    expect(validateLedger(result.ledger).ok).toBe(true);
  });
});

