  if (EXPECTED_BEHAVIOUR.test(text)) score += 0.25;
  if (task.body.trim().length >= 80) score += 0.2;
  if (STEPS_OR_OUTPUT.test(task.body)) score += 0.2;
  return round2(clamp01(score));
}

