import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
import { dirname } from 'node:path';
import { PriceHistory, type PriceHistorySnapshot } from '../agent/history.js';
import type { AttemptOutcome, PriceHistoryPort, PriceHistoryWriterPort, PriceStats } from '../agent/ports.js';
import type { TaskSize } from '../schema/types.js';

export interface HistoryFileStore {
  read(path: string): Promise<string>;
  write(path: string, body: string): Promise<void>;
  rename(from: string, to: string): Promise<void>;
  mkdir(path: string): Promise<void>;
}

export class NodeHistoryFileStore implements HistoryFileStore {
  async read(path: string): Promise<string> {
    return readFile(path, 'utf8');
  }

  async write(path: string, body: string): Promise<void> {
    await writeFile(path, body, 'utf8');
  }

  async rename(from: string, to: string): Promise<void> {
    await rename(from, to);
  }

  async mkdir(path: string): Promise<void> {
    await mkdir(path, { recursive: true });
  }
}

export interface FilePriceHistoryOptions {
  path: string;
  store?: HistoryFileStore;
}

/**
 * File-backed history for pass rate and average cost per (task size, tier/model).
 * Missing or unreadable files start empty, so the agent's prior still works.
 */
export class FilePriceHistory implements PriceHistoryPort, PriceHistoryWriterPort {
  private readonly path: string;
  private readonly store: HistoryFileStore;
  private loaded: Promise<PriceHistory> | null = null;
  private writeQueue: Promise<void> = Promise.resolve();

  constructor(options: FilePriceHistoryOptions) {
    this.path = options.path;
    this.store = options.store ?? new NodeHistoryFileStore();
  }

  async lookup(size: TaskSize, tierOrModel: string): Promise<PriceStats | null> {
    return (await this.history()).lookup(size, tierOrModel);
  }

  async record(outcome: AttemptOutcome): Promise<void> {
    this.writeQueue = this.writeQueue.then(async () => {
      const history = await this.history();
      await history.record(outcome);
      await this.persist(history.snapshot());
    });
    return this.writeQueue;
  }

  async snapshot(): Promise<PriceHistorySnapshot> {
    return (await this.history()).snapshot();
  }

  private async history(): Promise<PriceHistory> {
    this.loaded ??= this.load();
    return this.loaded;
  }

  private async load(): Promise<PriceHistory> {
    try {
      return new PriceHistory(JSON.parse(await this.store.read(this.path)) as PriceHistorySnapshot);
    } catch {
      return new PriceHistory();
    }
  }

  private async persist(snapshot: PriceHistorySnapshot): Promise<void> {
    await this.store.mkdir(dirname(this.path));
    const tmp = `${this.path}.tmp`;
    await this.store.write(tmp, `${JSON.stringify(snapshot, null, 2)}\n`);
    await this.store.rename(tmp, this.path);
  }
}
/**
 * Baseline mode: the "before" side of the comparison. Every task goes to the
 * strongest tier with no ceiling. Sizing still runs so ledger rows carry a
 * size, but it has no say in the decision.
 */
import { estimateFor } from './history.js';
import { usd, type RouteDecision, type RouteInput } from './router.js';
import { traceDecision } from './trace.js';

export async function routeBaseline(input: RouteInput): Promise<RouteDecision> {
  return traceDecision(
    input.ports.trace,
    'tally.baseline.route',
    { taskId: input.task.taskId, size: input.estimate.size, confidence: input.estimate.confidence },
    async (span) => {
      const { task, estimate, config } = input;
      const top = config.tiers[config.tiers.length - 1];
      if (!top) throw new Error('tally.yaml has no tiers');
      const common = { taskId: task.taskId, size: estimate.size, confidence: estimate.confidence };

      const remaining = await input.ports.budget.remainingNanos();
      if (remaining <= 0) {
        const decision = {
          ...common,
          action: 'skip' as const,
          statusReason: 'not started: no budget' as const,
          reason: `Not started because the budget is spent, with ${usd(Math.max(0, remaining))} left.`,
        };
        span.set({ action: decision.action, tier: null, ceilingNanos: null, reason: decision.reason });
        return decision;
      }
      const topCost = (await estimateFor(config, input.ports.history, estimate.size, top.name)).avgCostNanos;
      const decision = {
        ...common,
        action: 'start' as const,
        tier: top,
        ceilingNanos: null,
        expectedCostNanos: topCost,
        topCostNanos: topCost,
        reason: `Baseline mode sends every task straight to ${top.name} with no ceiling, so this ${estimate.size} task is not routed.`,
      };
      span.set({ action: decision.action, tier: top.name, ceilingNanos: null, reason: decision.reason });
      return decision;
    },
  );
}

