import { mkdtempSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { describe, expect, it } from 'vitest';
import { planTally } from './plan.js';

function fixture() {
  const dir = mkdtempSync(join(tmpdir(), 'tally-plan-'));
  const configPath = join(dir, 'tally.yaml');
  writeFileSync(
    configPath,
    `version: 1
repo: { path: ".", slug: "acme/demo", baseBranch: "main" }
test: { command: "npm test" }
backlog: { source: "file", file: "backlog.yaml" }
tiers:
  - name: cheap
    harness: claude-code
    provider: test
    model: cheap-model
    price: { inputUsdPerMTok: 1, cachedInputUsdPerMTok: 0, outputUsdPerMTok: 1 }
    ceilingFraction: 0.2
  - name: top
    harness: codex
    provider: test
    model: top-model
    price: { inputUsdPerMTok: 5, cachedInputUsdPerMTok: 0, outputUsdPerMTok: 5 }
    ceilingFraction: 1
ceilings:
  bySizeUsd: { small: 1, medium: 4, large: 10 }
budget: { source: config, usd: 10 }
integrations: { neatlogs: false, entire: false, cfoai: false, slack: false }
`,
  );
  writeFileSync(
    join(dir, 'backlog.yaml'),
    `tasks:
  - id: T1
    title: Fix \`calc.ts\` should add values
    body: Expected calc.ts to return a + b.
    size: small
`,
  );
  return configPath;
}

describe('planTally', () => {
  it('sizes and routes without worker ports', async () => {
    const plan = await planTally({
      configPath: fixture(),
      dryRun: true,
      baseline: false,
      signals: { async signalsFor() { return { filesTouched: 1, dependents: 0, testsPresent: true, source: 'code-search' }; } },
    });
    expect(plan).toHaveLength(1);
    expect(plan[0]).toMatchObject({ taskId: 'T1', size: 'small', tier: 'cheap', model: 'cheap-model', skipped: false });
    expect(plan[0]?.decision).toContain('expected to cost');
  });
});
import { mkdirSync, mkdtempSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { describe, expect, it } from 'vitest';
import { loadConfig } from './config.js';
import { validateRealRunConfig } from './preflight.js';
import { runTally } from './run.js';

function writeConfig(extraRepo = '') {
  const dir = mkdtempSync(join(tmpdir(), 'tally-preflight-'));
  const repo = join(dir, 'repo');
  mkdirSync(repo);
  writeFileSync(join(dir, 'backlog.yaml'), 'tasks:\n  - id: T1\n    title: Tiny fix\n    size: small\n');
  const configPath = join(dir, 'tally.yaml');
  writeFileSync(
    configPath,
    `version: 1
repo: { path: "repo", baseBranch: "main"${extraRepo} }
test: { command: "npm test" }
backlog: { source: "file", file: "backlog.yaml" }
tiers:
  - name: cheap
    harness: claude-code
    provider: test
    model: test-model
    price: { inputUsdPerMTok: 1, cachedInputUsdPerMTok: 0, outputUsdPerMTok: 1 }
    ceilingFraction: 1
ceilings:
  bySizeUsd: { small: 1, medium: 2, large: 3 }
budget: { source: config, usd: 10 }
integrations: { neatlogs: false, entire: false, cfoai: false, slack: false }
`,
  );
  return { configPath };
}

describe('real run preflight', () => {
  it('requires repo.aoProject before a real run can spawn a worker', async () => {
    const { configPath } = writeConfig();
    await expect(
      runTally({ configPath, dryRun: false, baseline: false, preflightRunner: async () => ({ stdout: '{}', stderr: '' }) }),
    ).rejects.toThrow('repo.aoProject is required');
  });

  it('checks that repo.aoProject exists in AO', async () => {
    const { configPath } = writeConfig(', aoProject: "missing-project"');
    await expect(
      validateRealRunConfig(loadConfig(configPath), configPath, async () => {
        throw new Error('not found');
      }),
    ).rejects.toThrow('ao project add');
  });
});
import { mkdirSync, writeFileSync } from 'node:fs';
import { mkdtemp } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { describe, expect, it } from 'vitest';
import { startDashboardServer } from './dashboard-server.js';

describe('dashboard server', () => {
  it('serves dashboard files and run data without directory listing or traversal', async () => {
    const dir = await mkdtemp(join(tmpdir(), 'tally-dashboard-'));
    const dashboardDir = join(dir, 'dashboard');
    const runsDir = join(dir, '.tally', 'runs');
    mkdirSync(join(runsDir, 'latest'), { recursive: true });
    mkdirSync(dashboardDir, { recursive: true });
    writeFileSync(join(dashboardDir, 'index.html'), '<h1>Tally</h1>');
    writeFileSync(join(dashboardDir, 'app.js'), 'export const ok = true;');
    writeFileSync(join(runsDir, 'latest', 'run.json'), '{"runId":"run-test","tasks":[],"budget":{"spentNanos":0,"limitNanos":1}}');
    writeFileSync(join(runsDir, 'latest', 'ledger.json'), '[]');
    writeFileSync(join(dir, 'secret.txt'), 'nope');

    const dashboard = await startDashboardServer({ port: 0, dashboardDir, runsDir });
    try {
      expect(dashboard.dataUrl).toBe('/runs/latest/');
      expect(dashboard.url).toContain(encodeURIComponent('/runs/latest/'));
      await expect((await fetch(dashboard.url)).text()).resolves.toContain('Tally');
      await expect((await fetch(new URL('/runs/latest/run.json', dashboard.url))).json()).resolves.toMatchObject({ runId: 'run-test' });
      expect((await fetch(new URL('/runs/', dashboard.url))).status).toBe(404);
      expect((await fetch(new URL('/runs/../secret.txt', dashboard.url))).status).toBe(404);
      expect((await fetch(new URL('/../secret.txt', dashboard.url))).status).toBe(404);
    } finally {
      await dashboard.close();
    }
  });
});

