import { existsSync } from 'node:fs';
import { resolve } from 'node:path';
import type { Ledger, RunState } from '../schema/index.js';
import { createDryRunPorts } from './dry-run.js';
import { runRealTally, type RealRunOptions } from './real.js';
import { DEFAULT_LATEST_RUN_DIR } from './output.js';
import { loadConfig } from './config.js';
import { validateRealRunConfig, type PreflightRunner } from './preflight.js';

export interface RunOptions {
  configPath: string;
  dryRun: boolean;
  baseline: boolean;
  budgetUsd?: number;
  only?: string;
  outputDir?: string;
  latestRunDir?: string;
  now?: () => Date;
  preflightRunner?: PreflightRunner;
}

export interface RunResult {
  runState: RunState;
  ledger: Ledger;
  outputDir: string;
  runStatePath: string;
  ledgerPath: string;
  latestRunDir: string;
}

export class RunError extends Error {
  constructor(readonly problems: string[]) {
    super(problems.join('; '));
    this.name = 'RunError';
  }
}

export async function runTally(options: RunOptions | RealRunOptions): Promise<RunResult> {
  if (!options.dryRun) await validateRealRunConfig(loadConfig(options.configPath), options.configPath, options.preflightRunner);
  const ports = options.dryRun ? { ...createDryRunPorts(), ...(options as RealRunOptions).ports } : (options as RealRunOptions).ports;
  return runRealTally({ ...(options as RealRunOptions), ...(ports ? { ports } : {}) });
}

function demoConfigPath(): string {
  const fromCwd = resolve('demo/tally.yaml');
  if (existsSync(fromCwd)) return fromCwd;
  return resolve(new URL('../demo/tally.yaml', import.meta.url).pathname);
}

export async function runDemo(options: Pick<RunOptions, 'outputDir' | 'latestRunDir' | 'now'> = {}): Promise<RunResult> {
  return runTally({
    configPath: demoConfigPath(),
    dryRun: true,
    baseline: false,
    outputDir: options.outputDir,
    latestRunDir: options.latestRunDir ?? DEFAULT_LATEST_RUN_DIR,
    now: options.now,
  });
}
import { costNanos } from '../schema/money.js';
import type { TallyConfig, TaskSize, Tier, TokenUsage } from '../schema/types.js';
import { PriceHistory } from '../agent/history.js';
import type { HandoffSummary, LiveUsage, LiveUsagePort, SessionControlPort, SizingSignals, SizingSignalsPort } from '../agent/ports.js';
import type { VerifierPort, VerifyInput, VerifyResult } from '../adapters/verifier.js';
import type { BacklogIntakePort } from '../adapters/github.js';
import { type BacklogTask, loadFileBacklog, type ScriptedAttempt } from './backlog.js';
import type { RealRunPorts, WorkerPort, WorkerResult, WorkerStartInput } from './real.js';

interface DrySession {
  sessionId: string;
  task: BacklogTask;
  attempt: number;
  tier: Tier;
  ceilingNanos: number | null;
  script: ScriptedAttempt;
  branch: string;
  checkoutPath: string;
  stopped: boolean;
  resolve?: (result: WorkerResult) => void;
}

class DryRunState implements BacklogIntakePort, SizingSignalsPort, WorkerPort, LiveUsagePort, SessionControlPort, VerifierPort {
  private readonly sessions = new Map<string, DrySession>();
  private readonly tasksById = new Map<string, BacklogTask>();

  async tasks(config: TallyConfig, configPath: string): Promise<BacklogTask[]> {
    const tasks = loadFileBacklog(config, configPath);
    this.tasksById.clear();
    for (const task of tasks) this.tasksById.set(task.taskId, task);
    return tasks;
  }

  async signalsFor(task: { taskId: string }): Promise<SizingSignals | null> {
    const size = this.tasksById.get(task.taskId)?.size;
    if (!size) return null;
    return signalsForSize(size);
  }

  async start(input: WorkerStartInput): Promise<{ sessionId: string; branch: string | null; checkoutPath: string | null }> {
    const scripts = input.task.scriptedAttempts ?? input.task.outcomes.map((result) => ({ result, resultReason: null, tokens: zeroTokens(), handoff: null, decision: null }));
    const script = scripts[input.attempt - 1] ?? scripts[scripts.length - 1];
    if (!script) throw new Error(`dry-run task ${input.task.taskId} has no scripted attempt ${input.attempt}`);
    const sessionId = `dry-${input.task.taskId}-${input.attempt}`;
    const branch = `dry/${input.task.taskId}/${input.attempt}`;
    const checkoutPath = `dry-run:${sessionId}`;
    this.sessions.set(sessionId, {
      sessionId,
      task: input.task,
      attempt: input.attempt,
      tier: input.tier,
      ceilingNanos: input.ceilingNanos,
      script,
      branch,
      checkoutPath,
      stopped: false,
    });
    return { sessionId, branch, checkoutPath };
  }

  async wait(sessionId: string): Promise<WorkerResult> {
    const session = this.session(sessionId);
    if (session.script.result !== 'stopped') return resultFor(session, 'idle');
    if (session.stopped) return resultFor(session, 'terminated');
    return new Promise((resolve) => {
      session.resolve = resolve;
    });
  }

  async usageFor(sessionId: string): Promise<LiveUsage | null> {
    const session = this.session(sessionId);
    const tokens = meteredTokens(session.script.tokens, session.tier, session.ceilingNanos, session.script.result);
    return { tokens, estimatedCostNanos: costNanos(tokens, session.tier.price) };
  }

  async stop(sessionId: string, _reason: string): Promise<void> {
    const session = this.session(sessionId);
    session.stopped = true;
    setTimeout(() => session.resolve?.(resultFor(session, 'terminated')), 0);
  }

  async verify(input: VerifyInput): Promise<VerifyResult> {
    const session = [...this.sessions.values()].find((candidate) => candidate.checkoutPath === input.checkoutPath || candidate.branch === input.branch);
    if (!session) return { passed: false, reason: 'dry-run session was not found' };
    if (session.script.result === 'passed') return { passed: true, reason: null };
    return { passed: false, reason: session.script.resultReason ?? `scripted ${session.script.result}` };
  }

  async summaryFor(sessionId: string): Promise<HandoffSummary | null> {
    const session = this.session(sessionId);
    const next = session.task.scriptedAttempts?.[session.attempt];
    const type = next?.handoff ?? 'entire-handoff';
    if (type === 'restart') return null;
    return {
      type,
      summary: `Dry-run handoff from ${session.task.taskId} attempt ${session.attempt}: ${session.script.resultReason ?? session.script.result}.`,
    };
  }

  private session(sessionId: string): DrySession {
    const session = this.sessions.get(sessionId);
    if (!session) throw new Error(`unknown dry-run session ${sessionId}`);
    return session;
  }
