  if (outputPriceNanos <= 0) return tokens;
  const neededOutput = Math.ceil((ceilingNanos - costNanos(tokens, tier.price)) / outputPriceNanos);
  return {
    ...tokens,
    output: tokens.output + neededOutput,
    total: tokens.total + neededOutput,
  };
}

