    const prUrl = session?.prs?.find((pr) => typeof pr.url === 'string')?.url ?? null;
    return {
      status,
      branch: session?.branch ?? null,
      checkoutPath: session?.checkoutPath ?? session?.worktreePath ?? session?.path ?? null,
      prUrl,
    };
  }
}
