149	// combined with `--session` (or `--continue`) -- resumed sessions inherit the
150	// approval settings of the original session -- so cfg.Permissions is
151	// intentionally ignored here.
152	func (p *Plugin) GetRestoreCommand(ctx context.Context, cfg ports.RestoreConfig) (cmd []string, ok bool, err error) {
153		// Deliberately does not forward cfg.Config.Model: --model + --session
154		// composition is unverified against a real kimi install (see #2890 and
155		// appendModelFlag). Pinned by TestGetRestoreCommandDoesNotForwardModelOverride.
156		if err := ctx.Err(); err != nil {
157			return nil, false, err
158		}
159		agentSessionID := strings.TrimSpace(cfg.Session.Metadata[ports.MetadataKeyAgentSessionID])
160		if agentSessionID == "" {
161			return nil, false, nil
162		}
163	
164		binary, err := p.kimiBinary(ctx)
165		if err != nil {
166			return nil, false, err
167		}
168		cmd = []string{binary, "--session", agentSessionID}
169		return cmd, true, nil
