208	func normalizePermissionMode(mode ports.PermissionMode) ports.PermissionMode {
209		switch mode {
210		case ports.PermissionModeDefault,
211			ports.PermissionModeAcceptEdits,
212			ports.PermissionModeAuto,
213			ports.PermissionModeBypassPermissions:
214			return mode
215		default:
216			return ports.PermissionModeDefault
217		}
218	}
