28	// GetAgentHooks installs AO's standing system prompt through Kimi's
29	// project-level instruction file. Kimi has no system-prompt argv flag, and its
30	// user-level config lives outside AO's data dir, so a gitignored worktree-local
31	// instruction file is the least invasive session-scoped injection point. It
32	// also installs Kimi lifecycle hooks into the AO-managed Kimi config so AO can
33	// capture Kimi's native session id for true resume without mutating the user's
34	// global Kimi profile.
35	func (p *Plugin) GetAgentHooks(ctx context.Context, cfg ports.WorkspaceHookConfig) error {
36		if err := ctx.Err(); err != nil {
37			return err
38		}
39		if strings.TrimSpace(cfg.WorkspacePath) == "" {
40			return errors.New("kimi.GetAgentHooks: WorkspacePath is required")
41		}
42	
43		if err := installKimiConfigHooks(cfg); err != nil {
44			return fmt.Errorf("kimi.GetAgentHooks: %w", err)
45		}
46	
47		systemPrompt, err := kimiSystemPromptText(cfg.SystemPrompt, cfg.SystemPromptFile)
48		if err != nil {
49			return fmt.Errorf("kimi.GetAgentHooks: %w", err)
50		}
51		if err := PrepareACPInstructions(ctx, cfg.WorkspacePath, systemPrompt); err != nil {
52			return fmt.Errorf("kimi.GetAgentHooks: %w", err)
53		}
54		return nil
55	}
