57	// PrepareACPInstructions installs AO's standing instructions where Kimi Code
58	// discovers project-level AGENTS.md files. Chat sessions call this immediately
59	// before launching `kimi acp`; unlike TUI sessions, they do not run
60	// GetAgentHooks during workspace preparation.
61	func PrepareACPInstructions(ctx context.Context, workspacePath, systemPrompt string) error {
62		if err := ctx.Err(); err != nil {
63			return err
64		}
65		if strings.TrimSpace(systemPrompt) == "" {
66			return nil
67		}
68		if strings.TrimSpace(workspacePath) == "" {
69			return errors.New("kimi: workspace path is required for ACP instructions")
70		}
71		instructionsPath := kimiInstructionsPath(workspacePath)
72		var existing []byte
73		existing, err := os.ReadFile(instructionsPath) //nolint:gosec // path built from caller-owned workspace dir
74		if err != nil && !errors.Is(err, os.ErrNotExist) {
75			return fmt.Errorf("kimi: read ACP instructions %s: %w", instructionsPath, err)
76		}
77		if err := ctx.Err(); err != nil {
78			return err
79		}
80	
81		if err := os.MkdirAll(filepath.Dir(instructionsPath), 0o750); err != nil {
82			return fmt.Errorf("kimi: create ACP instruction dir: %w", err)
83		}
84		if err := ctx.Err(); err != nil {
85			return err
86		}
87		body := mergeKimiInstructionFile(string(existing), systemPrompt)
88		if err := hookutil.AtomicWriteFile(instructionsPath, []byte(body), 0o600); err != nil {
89			return fmt.Errorf("kimi: write ACP instructions %s: %w", instructionsPath, err)
90		}
91		if err := ctx.Err(); err != nil {
92			return err
93		}
94		if err := hookutil.EnsureWorkspaceGitignore(filepath.Dir(instructionsPath), kimiInstructionsFileName); err != nil {
95			return fmt.Errorf("kimi: gitignore ACP instructions: %w", err)
96		}
97		return ctx.Err()
98	}
