104	func installKimiConfigHooks(cfg ports.WorkspaceHookConfig) error {
105		home, ok := kimiCodeHomeFromEnv(cfg.Env)
106		if !ok {
107			return errors.New("kimi: AO-managed Kimi Code home is unavailable")
108		}
109		if err := seedKimiCredentials(home); err != nil {
110			return err
111		}
112		path := filepath.Join(home, "config.toml")
113		data, err := os.ReadFile(path) //nolint:gosec // path is the AO-managed Kimi config under KIMI_CODE_HOME.
114		if err != nil && !errors.Is(err, os.ErrNotExist) {
115			return fmt.Errorf("read %s: %w", path, err)
116		}
117		if seeded, ok, err := kimiSeedConfig(path, data); err != nil {
118			return err
119		} else if ok {
120			data = seeded
121		}
122		body := mergeKimiHooksConfig(string(data))
123		if err := os.MkdirAll(filepath.Dir(path), 0o750); err != nil {
124			return fmt.Errorf("create Kimi config dir: %w", err)
125		}
126		if err := hookutil.AtomicWriteFile(path, []byte(body), 0o600); err != nil {
127			return fmt.Errorf("write %s: %w", path, err)
128		}
129		return nil
130	}
