132	func seedKimiCredentials(targetHome string) error {
133		sourceHome, ok := kimiCodeHome()
134		if !ok {
135			return nil
136		}
137		sourceConfigPath := filepath.Join(sourceHome, "config.toml")
138		sourcePaths, err := kimiConfigOAuthCredentialPaths(sourceConfigPath)
139		if err != nil {
140			return fmt.Errorf("read source Kimi config %s: %w", sourceConfigPath, err)
141		}
142		if len(sourcePaths) == 0 {
143			// Preserve the legacy credential-only seed path for profiles created by
144			// Kimi versions that did not persist an OAuth reference in config.toml.
145			sourcePaths = []string{filepath.Join(sourceHome, "credentials", "kimi-code.json")}
146		}
147		for _, sourcePath := range sourcePaths {
148			targetPath := filepath.Join(targetHome, "credentials", filepath.Base(sourcePath))
149			if err := seedKimiCredential(sourcePath, targetPath); err != nil {
150				return err
151			}
152		}
153		return nil
154	}
