231	func kimiSourceOAuthAuthorized(sourceHome string) (bool, error) {
232		configPath := filepath.Join(sourceHome, "config.toml")
233		paths, err := kimiConfigOAuthCredentialPaths(configPath)
234		if err != nil {
235			return false, fmt.Errorf("read source Kimi config %s: %w", configPath, err)
236		}
237		for _, path := range paths {
238			status, ok, err := kimiCredentialsAuthStatus(path)
239			if err != nil {
240				return false, fmt.Errorf("read source Kimi credentials %s: %w", path, err)
241			}
242			if ok && status == ports.AgentAuthStatusAuthorized {
243				return true, nil
244			}
245		}
246		return false, nil
247	}
