271	func kimiConfigHasAPIKey(data []byte) bool {
272		for _, match := range kimiAPIKeyLineRE.FindAllStringSubmatch(string(data), -1) {
273			for _, group := range match[2:] {
274				if strings.TrimSpace(group) != "" {
275					return true
276				}
277			}
278		}
279		return false
280	}
