293	// NativeConversationExists distinguishes Claude's reserved session UUID from
294	// a conversation that Claude has actually persisted. Claude Code accepts
295	// --session-id before the first prompt, but does not create its JSONL transcript
296	// until the conversation has content. Passing that reserved-but-empty UUID to
297	// either `claude --resume` or ACP session/load returns "No conversation found".
298	//
299	// The Agent SDK documents local transcripts at
300	// ~/.claude/projects/<project-key>/<session-id>.jsonl (or beneath
301	// CLAUDE_CONFIG_DIR). We only test for a non-empty top-level transcript; AO does
302	// not parse or project provider files here.
303	func (p *Plugin) NativeConversationExists(
304		ctx context.Context,
305		_ ports.SessionRef,
306		nativeConversationID string,
307		env map[string]string,
308	) (bool, error) {
309		if err := ctx.Err(); err != nil {
310			return false, err
311		}
312		id := strings.TrimSpace(nativeConversationID)
313		if !isUUID(id) {
314			return false, nil
315		}
316		configDir := strings.TrimSpace(env["CLAUDE_CONFIG_DIR"])
317		if configDir == "" {
318			configDir = strings.TrimSpace(os.Getenv("CLAUDE_CONFIG_DIR"))
319		}
320		if configDir == "" {
321			home, err := os.UserHomeDir()
322			if err != nil {
323				return false, fmt.Errorf("claude-code: resolve transcript root: %w", err)
324			}
325			configDir = filepath.Join(home, ".claude")
326		}
327		projectsDir := filepath.Join(configDir, "projects")
328		projects, err := os.ReadDir(projectsDir)
329		if os.IsNotExist(err) {
330			return false, nil
331		}
332		if err != nil {
333			return false, fmt.Errorf("claude-code: read transcript root %s: %w", projectsDir, err)
334		}
335		for _, project := range projects {
336			if err := ctx.Err(); err != nil {
337				return false, err
338			}
339			if !project.IsDir() {
340				continue
341			}
342			info, err := os.Stat(filepath.Join(projectsDir, project.Name(), id+".jsonl"))
343			switch {
344			case err == nil && info.Mode().IsRegular() && info.Size() > 0:
345				return true, nil
346			case err == nil, os.IsNotExist(err):
347				continue
348			default:
349				return false, fmt.Errorf("claude-code: inspect transcript for %s: %w", id, err)
350			}
351		}
352		return false, nil
353	}
