389	func claudeAuthStatusFromOutput(out []byte) (ports.AgentAuthStatus, bool) {
390		start := bytes.IndexByte(out, '{')
391		end := bytes.LastIndexByte(out, '}')
392		if start < 0 || end < start {
393			return ports.AgentAuthStatusUnknown, false
394		}
395		var status struct {
396			LoggedIn bool `json:"loggedIn"`
397		}
398		if json.Unmarshal(out[start:end+1], &status) != nil {
399			return ports.AgentAuthStatusUnknown, false
400		}
401		if status.LoggedIn {
402			return ports.AgentAuthStatusAuthorized, true
403		}
404		return ports.AgentAuthStatusUnauthorized, true
405	}
