408		if err := ctx.Err(); err != nil {
409			return ports.AgentAuthStatusUnknown, false, err
410		}
411		for _, name := range []string{"ANTHROPIC_API_KEY", "ANTHROPIC_AUTH_TOKEN", "CLAUDE_CODE_OAUTH_TOKEN"} {
412			if strings.TrimSpace(os.Getenv(name)) != "" {
413				return ports.AgentAuthStatusAuthorized, true, nil
414			}
415		}
416		cfgPath, err := claudeConfigPath()
