423	func claudeConfigAuthStatus(path string) (ports.AgentAuthStatus, bool, error) {
424		data, err := os.ReadFile(path)
425		if os.IsNotExist(err) {
426			return ports.AgentAuthStatusUnknown, false, nil
427		}
428		if err != nil {
429			return ports.AgentAuthStatusUnknown, false, err
430		}
431		if strings.TrimSpace(string(data)) == "" {
432			return ports.AgentAuthStatusUnknown, false, nil
433		}
434		var root map[string]json.RawMessage
435		if err := json.Unmarshal(data, &root); err != nil {
436			return ports.AgentAuthStatusUnknown, false, err
437		}
438		var hasSubscription bool
439		if raw := root["hasAvailableSubscription"]; len(raw) > 0 {
440			_ = json.Unmarshal(raw, &hasSubscription)
441		}
442		var userID string
443		if raw := root["userID"]; len(raw) > 0 {
444			_ = json.Unmarshal(raw, &userID)
445		}
446		if strings.TrimSpace(userID) != "" {
447			return ports.AgentAuthStatusAuthorized, true, nil
448		}
449		var oauthAccount map[string]any
