359	func codexTOMLString(value string) string {
360		if !containsTOMLControl(value) && !strings.Contains(value, "'") {
361			return "'" + value + "'"
362		}
363		var b strings.Builder
364		b.WriteByte('"')
365		for _, r := range value {
366			switch {
367			case r == '\\':
368				b.WriteString(`\\`)
369			case r == '"':
370				b.WriteString(`\"`)
371			case r < 0x20 || r == 0x7f:
372				fmt.Fprintf(&b, `\u%04X`, r)
373			default:
374				b.WriteRune(r)
375			}
376		}
377		b.WriteByte('"')
378		return b.String()
379	}
