159	func projectRelativeFile(projectPath, rel string) (string, error) {
160		if strings.TrimSpace(projectPath) == "" {
161			return "", fmt.Errorf("project path is required")
162		}
163		trimmed := strings.TrimSpace(rel)
164		if filepath.IsAbs(trimmed) || strings.HasPrefix(trimmed, "/") || strings.HasPrefix(trimmed, `\`) {
165			return "", fmt.Errorf("path must be repo-relative and must not escape the project root")
166		}
167		clean := filepath.Clean(trimmed)
168		if clean == "." || clean == ".." || strings.HasPrefix(clean, ".."+string(filepath.Separator)) {
169			return "", fmt.Errorf("path must be repo-relative and must not escape the project root")
170		}
171		for _, seg := range strings.Split(filepath.ToSlash(clean), "/") {
172			if seg == ".." {
173				return "", fmt.Errorf("path must be repo-relative and must not escape the project root")
174			}
175		}
176		return filepath.Join(projectPath, clean), nil
177	}
