219	// logged rather than returned: the spawn is already failing, and the caller's
220	// error is the one worth surfacing.
221	func (m *Manager) stopChatBestEffort(ctx context.Context, id domain.SessionID) {
222		if m.chat == nil {
223			return
224		}
