152	func (p *Plugin) GetRestoreCommand(ctx context.Context, cfg ports.RestoreConfig) (cmd []string, ok bool, err error) {
153		// Deliberately does not forward cfg.Config.Model: --model + --session
154		// composition is unverified against a real kimi install (see #2890 and
