360	// AuthStatus checks Claude Code's local authentication state without starting a
361	// session.
362	func (p *Plugin) AuthStatus(ctx context.Context) (ports.AgentAuthStatus, error) {
363		binary, err := p.claudeBinary(ctx)
364		if err != nil {
365			return ports.AgentAuthStatusUnknown, err
366		}
367		if status, ok, err := claudeLocalAuthStatus(ctx); err != nil {
368			return ports.AgentAuthStatusUnknown, err
369		} else if ok {
370			return status, nil
371		}
372		probeCtx, cancel := context.WithTimeout(ctx, 3*time.Second)
373		defer cancel()
374	
375		out, err := aoprocess.CommandContext(probeCtx, binary, "auth", "status").CombinedOutput()
376		if probeCtx.Err() != nil {
377			return ports.AgentAuthStatusUnknown, probeCtx.Err()
378		}
379		if status, ok := claudeAuthStatusFromOutput(out); ok {
380			return status, nil
381		}
382		// An unfamiliar non-zero result is not affirmative evidence of missing
383		// credentials. Keep this advisory probe unknown and let launch report the
384		// authoritative failure.
385		_ = err
386		return ports.AgentAuthStatusUnknown, nil
387	}
