220			cmd = append(cmd, "--session-id", ClaudeSessionID(cfg.SessionID))
221		}
222		cmd = append(cmd, ClaudePermissionArgs(cfg.Permission)...)
223		cmd = appendClaudeToolArgs(cmd, cfg.AllowedTools, cfg.DisallowedTools)
224		cmd = append(cmd, cfg.ProviderArgs...)
225		if model := strings.TrimSpace(cfg.Model); model != "" {
226			cmd = append(cmd, "--model", model)
227		}
228		var err error
229		cmd, err = appendClaudeSystemPrompt(cmd, cfg.SystemPromptFile, cfg.SystemPrompt)
230		if err != nil {
231			return nil, err
232		}
233		if cfg.Prompt != "" {
234			cmd = append(cmd, "--", cfg.Prompt)
