270	func appendClaudeSystemPrompt(cmd []string, promptFile, prompt string) ([]string, error) {
271		if promptFile != "" {
272			info, err := os.Stat(promptFile)
273			if err != nil {
274				return nil, fmt.Errorf("claude-code: inspect system prompt file: %w", err)
275			}
276			if !info.Mode().IsRegular() {
277				return nil, fmt.Errorf("claude-code: system prompt file %q is not a regular file", promptFile)
278			}
279			file, err := os.Open(promptFile) //nolint:gosec // path is host-owned launch config
280			if err != nil {
281				return nil, fmt.Errorf("claude-code: open system prompt file: %w", err)
282			}
