13	// The chat-mode controller launch.
14	//
15	// It is deliberately a separate path rather than conditionals threaded through
16	// the terminal launch: a chat session starts no agent process inside a runtime,
17	// has no pane to write into, and has no prompt-delivery strategy. Sharing that
18	// code would mean every step asking which kind of session it is in.
19	//
20	// What the two modes DO share is everything above this point — project
21	// resolution, prompts, the seed row, the worktree, provisioning, attachments —
22	// which is why the branch sits where it does and not higher.
23	
24	// ChatLauncher starts the structured controller for a chat session. Implemented
25	// by the chat service; nil in a build without chat support.
26	type ChatLauncher interface {
27		// SupportsChat reports whether a harness has a Chat driver at all, without
28		// probing the local install. Use it to decide whether Chat is even offerable.
29		SupportsChat(harness domain.AgentHarness) bool
30		// PreflightChat reports whether a harness can start in chat mode right now.
31		// Called before any durable state exists so an unsupported request costs
32		// nothing.
33		PreflightChat(ctx context.Context, harness domain.AgentHarness, permissions ports.PermissionMode) error
34		// StartChat launches the controller and returns the provider conversation
35		// handle to persist for resume. Implementations must call ControllerReady
36		// after the provider and generation exist but before consuming live events.
37		StartChat(ctx context.Context, cfg ChatStart) (ChatStarted, error)
38		// StartChatTurn delivers the initial prompt as a normal turn. There is no
39		// paste-and-Enter equivalent in chat mode: the provider either accepts the
40		// turn or reports why.
41		StartChatTurn(ctx context.Context, id domain.SessionID, text string) (string, error)
42		// RelayChatTurn delivers a message AO is carrying on someone else's behalf —
43		// `ao send`, an orchestrator writing to a worker, an automation — as a turn
44		// attributed to automation rather than to the human at the keyboard.
45		RelayChatTurn(ctx context.Context, id domain.SessionID, text string) (string, error)
46		// RelayChatTurnWithID is the durable-retry form. Implementations must pass
47		// the key through to ChatUserMessage so retry after an uncertain outbox
48		// acknowledgement cannot create a second provider turn.
49		RelayChatTurnWithID(ctx context.Context, id domain.SessionID, text, clientMessageID string) (string, error)
50		// HasLiveChatController reports whether the daemon still owns a controller
51		// for the session. Resume uses this to distinguish a stale durable activity
52		// state left by an older daemon from a genuinely live controller.
53		HasLiveChatController(id domain.SessionID) bool
54		// StopChat releases a session's controller.
55		StopChat(ctx context.Context, id domain.SessionID) error
56	}
