94	// launchChatController starts the provider controller for a chat session and
95	// marks it spawned.
96	//
97	// Rollback mirrors the terminal path's: a failure before the controller exists
98	// tears the workspace down, and a failure after it exists closes the controller
99	// first so no app-server process is left behind holding the worktree.
100	func (m *Manager) launchChatController(ctx context.Context, in chatSpawn) (domain.SessionRecord, error) {
101		id := in.record.ID
102		releaseCodexAdmission, err := m.acquireCodexControllerAdmission(ctx, in.cfg.Harness)
103		if err != nil {
104			m.rollbackSeedSpawnWorkspace(ctx, in.record, in.workspace, in.workspaceProject, false)
105			return domain.SessionRecord{}, wrapSpawnStage(id, ErrChatController, err)
106		}
107		defer releaseCodexAdmission()
108		agentConfig := in.cfg.AgentConfig
109		if !in.cfg.AgentConfigResolved {
110			agentConfig = applySpawnAgentConfig(effectiveAgentConfig(in.cfg.Harness, in.cfg.Kind, in.project.Config), in.cfg.AgentConfig)
111		}
112	
113		var diffBaseSHA, diffBaseRef string
114		if in.projectKind == domain.ProjectKindSingleRepo {
115			diffBaseSHA, diffBaseRef = resolveSpawnDiffBase(
116				ctx, in.workspace.Path, in.workspace.BaseRef)
117		}
118		// Chat Service retains this unprivileged base environment. The bearer is
119		// minted inside its per-session launch gate and is never cached for reuse.
120		env := m.runtimeEnv(id, in.record.ProjectID, in.record.IssueID, in.project.Config.Env)
121		if agent, ok := m.agents.Agent(in.cfg.Harness); ok {
122			m.augmentAgentRuntimeEnv(agent, env)
123		}
124	
125		var (
126			controllerCommitted bool
127			completionErr       error
128		)
129		_, err = m.chat.StartChat(ctx, ChatStart{
130			SessionID:               id,
131			ProjectID:               in.cfg.ProjectID,
132			Kind:                    in.cfg.Kind,
133			Harness:                 in.cfg.Harness,
134			DataDir:                 m.dataDir,
135			WorkspacePath:           in.workspace.Path,
136			Env:                     env,
137			Model:                   agentConfig.Model,
138			Effort:                  agentConfig.Effort,
139			Permissions:             agentConfig.Permissions,
140			SystemPrompt:            in.systemPrompt,
141			AdditionalDirectories:   workspaceProjectDirectories(in.workspace.Path, in.workspaceProject),
142			ExpectedControllerOwner: in.record.ControllerOwner(),
143			PrepareControllerEnv: func(launchCtx context.Context, expected domain.SessionControllerOwner) (map[string]string, error) {
144				prepared, launchEnv, prepareErr := m.prepareChatControllerEnv(
145					launchCtx, in.record, in.project.Config.Env, expected,
146				)
147				if prepareErr != nil {
148					return nil, fmt.Errorf("%w: %w", ErrSpawnBrowser, prepareErr)
149				}
150				if agent, ok := m.agents.Agent(in.cfg.Harness); ok {
151					m.augmentAgentRuntimeEnv(agent, launchEnv)
152				}
153				in.record = prepared
154				return launchEnv, nil
155			},
156			ControllerReady: func(started ChatStarted) (ChatControllerCommit, error) {
157				metadata := domain.SessionMetadata{
158					Permissions:       in.record.Metadata.Permissions,
159					Branch:            in.workspace.Branch,
160					WorkspacePath:     in.workspace.Path,
161					WorkspaceRepoPath: in.workspace.RepoPath,
162					Prompt:            in.prompt,
163					DiffBaseSHA:       diffBaseSHA,
164					DiffBaseRef:       diffBaseRef,
165					// No RuntimeHandleID or RuntimeLaunchID: a chat session has no
166					// agent pane. Leaving them empty keeps the reaper from probing for
167					// a terminal that was never created.
168					ProviderConversationID:    started.ProviderConversationID,
169					ControllerGeneration:      started.ControllerGeneration,
170					BrowserCapabilityVerifier: in.record.Metadata.BrowserCapabilityVerifier,
171					Model:                     agentConfig.Model,
172				}
173				committedConversation, commitErr := m.markChatControllerSpawned(
174					ctx, id, metadata, started.Conversation, started.ProviderBoundary,
175					started.CommitProviderHistory, nil, started.LiveReconnect,
176				)
177				completionErr = commitErr
178				controllerCommitted = completionErr == nil
179				return ChatControllerCommit{
180					Conversation: committedConversation,
181					ControllerOwner: chatControllerOwner(
182						in.record, in.cfg.Harness, started.ProviderConversationID, started.ControllerGeneration,
183					),
184				}, completionErr
185			},
186		})
187		if err != nil {
188			if completionErr != nil || controllerCommitted {
189				m.stopChatBestEffort(ctx, id)
190				m.rollbackPreparedSpawnWorkspace(ctx, in.record, in.workspace, in.workspaceProject, true)
191				m.markSpawnFailedTerminated(ctx, id)
192				if completionErr != nil {
193					return domain.SessionRecord{}, wrapSpawnStage(id, ErrSpawnCommit, completionErr)
194				}
195				return domain.SessionRecord{}, wrapSpawnStage(id, ErrChatController, err)
196			}
197			// No controller exists, so nothing provider-side needs closing. The
198			// runtime was never touched, hence runtimeDestroyed=false.
199			m.rollbackSeedSpawnWorkspace(ctx, in.record, in.workspace, in.workspaceProject, false)
200			return domain.SessionRecord{}, wrapSpawnStage(id, ErrChatController, err)
201		}
202	
203		// The initial prompt is a normal turn through the controller. There is no
204		// paste-and-Enter equivalent here, and no "deliver after start" variant: the
205		// provider either accepts the turn or reports why.
206		if in.prompt != "" {
207			if _, err := m.chat.StartChatTurn(ctx, id, in.prompt); err != nil {
208				m.stopChatBestEffort(ctx, id)
209				m.rollbackPreparedSpawnWorkspace(ctx, in.record, in.workspace, in.workspaceProject, true)
210				m.markSpawnFailedTerminated(ctx, id)
211				return domain.SessionRecord{}, wrapSpawnStage(id, ErrSpawnDeliverPrompt, err)
212			}
213		}
214	
215		return m.getRecord(ctx, id)
216	}
