218	// stopChatBestEffort closes a controller during rollback. A failure here is
219	// logged rather than returned: the spawn is already failing, and the caller's
220	// error is the one worth surfacing.
221	func (m *Manager) stopChatBestEffort(ctx context.Context, id domain.SessionID) {
222		if m.chat == nil {
223			return
224		}
225		if err := m.chat.StopChat(ctx, id); err != nil {
226			m.logger.Warn("spawn rollback: close chat controller", "sessionID", id, "error", err)
227		}
228	}
