230	// sendChat routes an outbound message into a chat session's conversation.
231	//
232	// It reports handled=false for anything that is not a live chat session, so the
233	// terminal path below it is reached unchanged — including for a session this
234	// build cannot serve, where the runtime guard's refusal is still the right answer.
235	//
236	// The refusals here mirror the terminal path's: a terminated session cannot
237	// receive a message, and one whose controller is gone cannot either. Busy is not
238	// a refusal — the controller queues a mid-turn message, which is strictly better
239	// than the terminal path's habit of dropping a nudge it cannot safely deliver.
240	func (m *Manager) sendChat(ctx context.Context, id domain.SessionID, message, clientMessageID string) (bool, error) {
241		rec, ok, err := m.store.GetSession(ctx, id)
242		if err != nil {
243			return false, fmt.Errorf("send %s: session: %w", id, err)
244		}
245		if !ok || domain.NormalizeSessionMode(rec.Mode) != domain.SessionModeChat {
246			return false, nil
247		}
248		if m.chat == nil {
249			return true, fmt.Errorf("send %s: %w: chat mode is not available in this build",
250				id, ports.ErrChatUnsupported)
251		}
252		if rec.IsTerminated {
253			return true, fmt.Errorf("send %s: %w", id, ErrTerminated)
254		}
255		var relayErr error
256		if clientMessageID != "" {
257			_, relayErr = m.chat.RelayChatTurnWithID(ctx, id, message, clientMessageID)
258		} else {
259			_, relayErr = m.chat.RelayChatTurn(ctx, id, message)
260		}
261		if relayErr != nil {
262			return true, fmt.Errorf("send %s: %w", id, relayErr)
263		}
264		return true, nil
265	}
