291	// resumeChatController reattaches a chat session to its provider conversation
292	// after a daemon restart.
293	//
294	// It resumes the stored conversation rather than starting a new one. A resume
295	// that fails is reported, not silently replaced with a fresh conversation:
296	// presenting unrelated history as continuous is worse than an error the user can
297	// act on, and it would strand the work the old conversation was holding.
298	func (m *Manager) resumeChatController(
299		ctx context.Context,
300		operation string,
301		rec domain.SessionRecord,
302		project domain.ProjectRecord,
303		ws ports.WorkspaceInfo,
304		requireNativeHistory bool,
305		controllerGeneration string,
306		historyPolicy domain.SessionInterfaceTransitionHistoryPolicy,
307	) (RestoreResult, error) {
308		if m.chat == nil {
309			return RestoreResult{}, fmt.Errorf("%s %s: %w: chat mode is not available in this build",
310				operation, rec.ID, ports.ErrChatUnsupported)
311		}
312		releaseCodexAdmission, err := m.acquireCodexControllerAdmission(ctx, rec.Harness)
313		if err != nil {
314			return RestoreResult{}, fmt.Errorf("%s %s: %w", operation, rec.ID, err)
315		}
316		defer releaseCodexAdmission()
317	
318		// Recomputed rather than persisted, matching the terminal path: a restored
319		// session keeps its standing instructions across the relaunch.
320		systemPrompt, err := m.buildSystemPrompt(ctx, rec.Kind, rec.ProjectID)
321		if err != nil {
322			return RestoreResult{}, fmt.Errorf("%s %s: system prompt: %w", operation, rec.ID, err)
323		}
324		systemPrompt, err = m.systemPromptForNativeRestore(ctx, rec, systemPrompt)
325		if err != nil {
326			return RestoreResult{}, fmt.Errorf("%s %s: switched continuation: %w", operation, rec.ID, err)
327		}
328	
329		agentConfig := restoredAgentConfig(rec, project.Config)
330		if rec.Metadata.Permissions != "" {
331			agentConfig.Permissions = rec.Metadata.Permissions
332		}
333		additionalDirectories, err := m.restoredWorkspaceProjectDirectories(ctx, rec, project, ws.Path)
334		if err != nil {
335			return RestoreResult{}, fmt.Errorf("%s %s: workspace roots: %w", operation, rec.ID, err)
336		}
337		env := m.runtimeEnv(rec.ID, rec.ProjectID, rec.IssueID, project.Config.Env)
338		if agent, ok := m.agents.Agent(rec.Harness); ok {
339			m.augmentAgentRuntimeEnv(agent, env)
340		}
341		historyMode := ports.ChatHistoryImport
342		var providerHandoff *domain.ChatProviderHandoff
343		if requireNativeHistory {
344			historyMode = ports.ChatHistoryRequired
345			providerHandoff, err = m.prepareLiveChatProviderHandoff(ctx, rec)
346		} else {
347			providerHandoff, err = m.prepareRecoveredChatProviderHandoff(ctx, rec)
348		}
349		if err != nil {
350			return RestoreResult{}, fmt.Errorf("%s %s: recover provider ownership: %w", operation, rec.ID, err)
351		}
352		var completionErr error
353		_, err = m.chat.StartChat(ctx, ChatStart{
354			SessionID:               rec.ID,
355			ProjectID:               rec.ProjectID,
356			Kind:                    rec.Kind,
357			Harness:                 rec.Harness,
358			DataDir:                 m.dataDir,
359			WorkspacePath:           ws.Path,
360			Env:                     env,
361			Model:                   agentConfig.Model,
362			Effort:                  agentConfig.Effort,
363			Permissions:             agentConfig.Permissions,
364			SystemPrompt:            systemPrompt,
365			AdditionalDirectories:   additionalDirectories,
366			ExpectedControllerOwner: rec.ControllerOwner(),
367			PrepareControllerEnv: func(launchCtx context.Context, expected domain.SessionControllerOwner) (map[string]string, error) {
368				prepared, launchEnv, prepareErr := m.prepareChatControllerEnv(
369					launchCtx, rec, project.Config.Env, expected,
370				)
371				if prepareErr != nil {
372					return nil, prepareErr
373				}
374				if agent, ok := m.agents.Agent(rec.Harness); ok {
375					m.augmentAgentRuntimeEnv(agent, launchEnv)
376				}
377				rec = prepared
378				return launchEnv, nil
379			},
380			// The handle that makes this a resume rather than a new conversation.
381			ProviderConversationID: rec.Metadata.ProviderConversationID,
382			ProviderHandoff:        providerHandoff,
383			// Ordinary resumes allocate a fresh generation. Switch recovery reuses
384			// the saga's reserved generation until delivery is durably settled so a
385			// second restart can still prove exact target ownership.
386			ControllerGeneration: controllerGeneration,
387			HistoryMode:          historyMode,
388			HistoryPolicy:        historyPolicy,
389			ControllerReady: func(started ChatStarted) (ChatControllerCommit, error) {
390				metadata := rec.Metadata
391				metadata.WorkspacePath = ws.Path
392				metadata.WorkspaceRepoPath = ws.RepoPath
393				if ws.Branch != "" {
394					metadata.Branch = ws.Branch
