436	func (m *Manager) markChatControllerSpawned(
437		ctx context.Context,
438		id domain.SessionID,
439		metadata domain.SessionMetadata,
440		conversation domain.ConversationRecord,
441		providerBoundary *domain.ConversationBranch,
442		commitProviderHistory func(context.Context) error,
443		handoff *domain.ChatProviderHandoff,
444		liveReconnect bool,
445	) (domain.ConversationRecord, error) {
446		if liveReconnect {
447			if providerBoundary != nil {
448				return domain.ConversationRecord{}, errors.New("live Chat reconnect cannot replace the provider boundary")
449			}
450			return conversation, m.lcm.MarkChatReconnected(ctx, id, metadata)
451		}
452		if handoff != nil && (providerBoundary == nil || commitProviderHistory == nil) {
453			return domain.ConversationRecord{}, errors.New("native Chat handoff requires atomic history publication")
454		}
455		if providerBoundary == nil {
456			return conversation, m.lcm.MarkSpawned(ctx, id, metadata)
457		}
