172	// appendApprovalFlags maps AO's permission modes onto Kimi's approval flags
173	// for interactive launches. Per Kimi docs these flags cannot be combined with
174	// `--prompt`, `--session`, or `--continue`, so callers on those paths must
175	// skip this mapping.
176	//
177	//   - Default: no flag, deferring to the user's Kimi config/default behavior.
178	//   - AcceptEdits / Auto: `--auto` (auto permission mode; approvals handled
179	//     automatically).
180	//   - BypassPermissions: `-y` (yolo; auto-approve regular tool calls including
181	//     file writes and shell execution).
182	func appendApprovalFlags(cmd *[]string, permissions ports.PermissionMode) {
183		switch normalizePermissionMode(permissions) {
184		case ports.PermissionModeDefault:
185			// No flag: defer to the user's Kimi config/default behavior.
186		case ports.PermissionModeAcceptEdits, ports.PermissionModeAuto:
187			*cmd = append(*cmd, "--auto")
188		case ports.PermissionModeBypassPermissions:
189			*cmd = append(*cmd, "-y")
190		}
191	}
