194	// override is configured. A blank/whitespace-only value means no override was
195	// configured, so the flag is omitted and Kimi's own default model applies.
196	//
197	// Restore-path note: this is intentionally NOT called from
198	// GetRestoreCommand. Kimi's docs do not confirm --model composes with
199	// --session the way it does on the launch path (see issue #2890); wiring it
200	// blind risks silently breaking session resume. Left as a fast-follow pending
201	// verification against a real kimi install.
202	func appendModelFlag(cmd *[]string, cfg ports.AgentConfig) {
203		if model := strings.TrimSpace(cfg.Model); model != "" {
204			*cmd = append(*cmd, "--model", model)
205		}
206	}
