194	func kimiSeedConfig(targetPath string, existing []byte) ([]byte, bool, error) {
195		if kimiConfigHasAPIKey(existing) {
196			return nil, false, nil
197		}
198		if !kimiConfigCanSeed(existing) {
199			return nil, false, nil
200		}
201		sourceHome, ok := kimiCodeHome()
202		if !ok {
203			return nil, false, nil
204		}
205		sourcePath := filepath.Join(sourceHome, "config.toml")
206		if sameKimiConfigPath(sourcePath, targetPath) {
207			return nil, false, nil
208		}
209		source, err := os.ReadFile(sourcePath) //nolint:gosec // user/process Kimi config used only as a seed for AO-managed home.
210		if errors.Is(err, os.ErrNotExist) {
211			return nil, false, nil
212		}
213		if err != nil {
214			return nil, false, fmt.Errorf("read source Kimi config %s: %w", sourcePath, err)
215		}
216		if !kimiConfigHasAPIKey(source) {
217			// Device-code logins leave api_key empty and keep their tokens in the
218			// credential file. The full config is still required for default_model,
219			// the provider/OAuth mapping, model aliases, services, and permissions.
220			authorized, err := kimiSourceOAuthAuthorized(sourceHome)
221			if err != nil {
222				return nil, false, err
223			}
224			if !authorized {
225				return nil, false, nil
226			}
227		}
228		return source, true, nil
229	}
