257	func removeKimiManagedHooks(existing string) string {
258		start := strings.Index(existing, kimiHooksSentinelStart)
259		if start < 0 {
260			return existing
261		}
262		afterStart := existing[start+len(kimiHooksSentinelStart):]
263		endRel := strings.Index(afterStart, kimiHooksSentinelEnd)
264		if endRel < 0 {
265			return strings.TrimRight(existing[:start], "\n")
266		}
267		end := start + len(kimiHooksSentinelStart) + endRel + len(kimiHooksSentinelEnd)
268		return existing[:start] + existing[end:]
269	}
