291	func mergeKimiHooksConfig(existing string) string {
292		block := kimiHooksConfigBlock()
293		start := strings.Index(existing, kimiHooksSentinelStart)
294		if start < 0 {
295			return joinKimiConfigParts(existing, block, "")
296		}
297		afterStart := existing[start+len(kimiHooksSentinelStart):]
298		endRel := strings.Index(afterStart, kimiHooksSentinelEnd)
299		if endRel < 0 {
300			return joinKimiConfigParts(existing[:start], block, "")
301		}
302		end := start + len(kimiHooksSentinelStart) + endRel + len(kimiHooksSentinelEnd)
303		return joinKimiConfigParts(existing[:start], block, existing[end:])
304	}
