315	func kimiHookEntry(event, matcher, command string) string {
316		var b strings.Builder
317		b.WriteString("[[hooks]]\n")
318		b.WriteString("event = ")
319		b.WriteString(quoteTOMLString(event))
320		b.WriteByte('\n')
321		if matcher != "" {
322			b.WriteString("matcher = ")
323			b.WriteString(quoteTOMLString(matcher))
324			b.WriteByte('\n')
325		}
326		b.WriteString("command = ")
327		b.WriteString(quoteTOMLString(command))
328		b.WriteByte('\n')
329		b.WriteString("timeout = 5\n\n")
330		return b.String()
331	}
