136	// GetLaunchCommand builds the argv to start an interactive Claude Code
137	// session. Shape:
138	//
139	//	claude [--session-id <uuid>] \
140	//	       [--permission-mode <mode>] \
141	//	       [--append-system-prompt-file <path> | --append-system-prompt <text>] \
142	//	       [-- <prompt>]
143	//
144	// --session-id pins Claude's native session UUID to LaunchConfig.NativeSessionID
145	// when AO requests a distinct provider conversation, otherwise to a value
146	// derived from the AO session id for the legacy one-conversation path. This
147	// makes the session resumable later (see
148	// GetRestoreCommand) and its transcript is locatable (see SessionInfo) without
149	// a separate capture step.
150	//
151	// <mode> is acceptEdits, auto, or bypassPermissions. AO's "default"
152	// mode emits no --permission-mode flag, so Claude's TUI resolves the starting
153	// mode from ~/.claude/settings.json exactly as a normal launch.
154	//
155	// The prompt is passed after `--` so a prompt beginning with "-" is not
156	// mistaken for a flag.
157	func (p *Plugin) GetLaunchCommand(ctx context.Context, cfg ports.LaunchConfig) (cmd []string, err error) {
158		// Defense-in-depth: the project service validates on write, but re-check
159		// here so a config written by any other path can't launch a bad command.
160		if err := cfg.Config.Validate(); err != nil {
161			return nil, fmt.Errorf("claude-code: %w", err)
162		}
163	
164		binary, err := p.claudeBinary(ctx)
165		if err != nil {
166			return nil, err
167		}
168	
169		// A project's configured permissions drive the starting mode; the explicit
170		// LaunchConfig.Permissions wins when set so a per-spawn override still takes
171		// precedence over the stored project default.
172		permissions := cfg.Permissions
173		if permissions == "" {
174			permissions = cfg.Config.Permissions
175		}
176		return agentruntime.BuildLaunchCommand(agentruntime.LaunchConfig{
177			Harness:          agentruntime.HarnessClaudeCode,
178			Binary:           binary,
179			SessionID:        cfg.SessionID,
180			NativeSessionID:  cfg.NativeSessionID,
181			Model:            cfg.Config.Model,
182			Prompt:           cfg.Prompt,
183			SystemPrompt:     cfg.SystemPrompt,
184			SystemPromptFile: cfg.SystemPromptFile,
185			Permission:       agentruntime.PermissionPolicy(permissions),
186			AllowedTools:     cfg.AllowedTools,
187			DisallowedTools:  cfg.DisallowedTools,
188		})
189	}
