574	func ensureWorkspaceTrustedForOS(configPath, workspacePath, goos string) error {
575		claudeTrustMu.Lock()
576		defer claudeTrustMu.Unlock()
577		if goos == "windows" {
578			workspacePath = strings.ReplaceAll(workspacePath, `\`, "/")
579		}
580	
581		root := map[string]any{}
582		data, err := os.ReadFile(configPath)
583		switch {
584		case err == nil:
585			if len(bytes.TrimSpace(data)) == 0 {
586				// A zero-byte read means we may have caught some other writer
587				// mid-truncate. Treat it like a corrupt file, not a missing
588				// one: refuse to write rather than silently replacing the
589				// user's real config (oauthAccount, projects history, etc.)
590				// with one containing only the trust entry.
591				return fmt.Errorf("claude-code: %s is empty; refusing to overwrite", configPath)
592			}
593			if err := json.Unmarshal(data, &root); err != nil {
594				return fmt.Errorf("claude-code: parse %s: %w", configPath, err)
595			}
596		case os.IsNotExist(err):
597			// Treat as empty config; we'll create it.
598		default:
599			return fmt.Errorf("claude-code: read %s: %w", configPath, err)
600		}
601	
602		projects, _ := root["projects"].(map[string]any)
603		if projects == nil {
604			projects = map[string]any{}
605			root["projects"] = projects
606		}
607	
608		entry, _ := projects[workspacePath].(map[string]any)
609		if entry == nil {
610			entry = map[string]any{}
611			projects[workspacePath] = entry
612		}
613	
614		if trusted, ok := entry["hasTrustDialogAccepted"].(bool); ok && trusted {
615			// Already trusted — no write needed, so no race window at all.
616			return nil
617		}
618		entry["hasTrustDialogAccepted"] = true
619	
620		out, err := json.MarshalIndent(root, "", "  ")
621		if err != nil {
622			return fmt.Errorf("claude-code: encode %s: %w", configPath, err)
623		}
624	
625		// Atomic write: temp file in the same directory, then rename. Matches
626		// how Claude Code itself updates this file, so concurrent updates are
627		// last-writer-wins rather than corrupting.
628		dir := filepath.Dir(configPath)
629		tmp, err := os.CreateTemp(dir, ".claude.json.tmp-*")
630		if err != nil {
631			return fmt.Errorf("claude-code: create temp config: %w", err)
632		}
633		tmpName := tmp.Name()
634		defer func() { _ = os.Remove(tmpName) }() // no-op once renamed
635	
636		if _, err := tmp.Write(out); err != nil {
637			_ = tmp.Close()
638			return fmt.Errorf("claude-code: write temp config: %w", err)
639		}
640		if err := tmp.Close(); err != nil {
641			return fmt.Errorf("claude-code: close temp config: %w", err)
642		}
643		if err := os.Rename(tmpName, configPath); err != nil {
644			return fmt.Errorf("claude-code: replace config: %w", err)
645		}
646		return nil
