272	// resolveSessionMode applies the precedence for a spawn:
273	//
274	//  1. the mode the caller explicitly requested;
275	//  2. the daemon-owned default;
276	//  3. the compatibility default, TUI.
277	//
278	// The default is read here, at spawn time, so changing the preference affects only
279	// sessions created afterwards. An existing session changes only through an explicit,
280	// capability-gated interface transition; it is never re-resolved from the default.
281	func (m *Manager) resolveSessionMode(ctx context.Context, requested domain.SessionMode) domain.SessionMode {
282		if requested.Valid() {
283			return requested
284		}
285		if m.defaults == nil {
286			return domain.DefaultSessionMode
287		}
288		return domain.NormalizeSessionMode(m.defaults.DefaultSessionMode(ctx))
289	}
