490	func workspaceProjectDirectories(root string, project *ports.WorkspaceProjectInfo) []string {
491		if project == nil {
492			return nil
493		}
494		root = filepath.Clean(root)
495		directories := make([]string, 0, len(project.Worktrees))
496		for _, worktree := range project.Worktrees {
497			if worktree.Path == "" || filepath.Clean(worktree.Path) == root {
498				continue
499			}
500			directories = append(directories, worktree.Path)
501		}
502		return directories
