156	func seedKimiCredential(sourcePath, targetPath string) error {
157		if sameKimiConfigPath(sourcePath, targetPath) {
158			return nil
159		}
160		if _, err := os.Stat(targetPath); err == nil {
161			return nil
162		} else if !errors.Is(err, os.ErrNotExist) {
163			return fmt.Errorf("stat target Kimi credentials %s: %w", targetPath, err)
164		}
165		status, ok, err := kimiCredentialsAuthStatus(sourcePath)
166		if err != nil {
167			return fmt.Errorf("read source Kimi credentials %s: %w", sourcePath, err)
168		}
169		if !ok || status != ports.AgentAuthStatusAuthorized {
170			return nil
171		}
172		data, err := os.ReadFile(sourcePath) //nolint:gosec // user Kimi credentials copied into AO's isolated Kimi home.
173		if err != nil {
174			return fmt.Errorf("read source Kimi credentials %s: %w", sourcePath, err)
175		}
176		if err := os.MkdirAll(filepath.Dir(targetPath), 0o700); err != nil {
177			return fmt.Errorf("create target Kimi credentials dir: %w", err)
178		}
179		if err := hookutil.AtomicWriteFile(targetPath, data, 0o600); err != nil {
180			return fmt.Errorf("write target Kimi credentials %s: %w", targetPath, err)
181		}
182		return nil
183	}
