function fixture(integrations = 'neatlogs: false, entire: false, cfoai: false, slack: false') {
  const dir = mkdtempSync(join(tmpdir(), 'tally-real-'));
  const configPath = join(dir, 'tally.yaml');
  writeFileSync(
