    await sdk?.flush?.();
    await sdk?.shutdown?.();
  }

  private async ready(): Promise<NeatlogsSdk | null> {
    if (this.sdk || this.offReason) return this.sdk;
    this.initStarted ??= this.initialise();
    await this.initStarted;
    return this.sdk;
